import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Erasure Coding Enhancements for Tentacle","description":"","frontmatter":{"title":"Erasure Coding Enhancements for Tentacle","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph","压缩冗余编码","分布式存储","性能优化","BlueStore"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Erasure_Coding_Enhancements_for_Tentacle.md","filePath":"posts/2025/Erasure_Coding_Enhancements_for_Tentacle.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Erasure_Coding_Enhancements_for_Tentacle.md"};function i(n,a,s,h,d,c){return r(),t("div",null,[...a[0]||(a[0]=[l('<h3 id="ceph-分布式存储-erasure-coding-性能优化进展" tabindex="-1">Ceph 分布式存储 Erasure Coding 性能优化进展 <a class="header-anchor" href="#ceph-分布式存储-erasure-coding-性能优化进展" aria-label="Permalink to &quot;Ceph 分布式存储 Erasure Coding 性能优化进展&quot;">​</a></h3><p><strong>会议主题</strong>：Ceph 的 Erasure Coding (EC) 性能优化进展<br><strong>主讲人</strong>：Bill（IBM 高级技术专家）、Alex Aninsko（IBM 高级技术成员）<br><strong>会议时间</strong>：近期（具体日期未标注）</p><h4 id="_1-会议背景与目标" tabindex="-1">1. 会议背景与目标 <a class="header-anchor" href="#_1-会议背景与目标" aria-label="Permalink to &quot;1. 会议背景与目标&quot;">​</a></h4><ul><li><strong>背景</strong>：Ceph 的 EC 编码（如 3-way 副本）存储效率较低，成本较高。</li><li><strong>目标</strong>：通过算法优化减少 IO 操作，提升 BlueStore 效率，降低 CPU 和网络开销，最终降低 TCO。</li><li><strong>核心优化点</strong>： <ul><li>减少对存储设备的 IO 请求。</li><li>与 Crimson 等其他性能优化方案互补。</li></ul></li></ul><h4 id="_2-主要优化内容" tabindex="-1">2. 主要优化内容 <a class="header-anchor" href="#_2-主要优化内容" aria-label="Permalink to &quot;2. 主要优化内容&quot;">​</a></h4><h4 id="_1-功能实现" tabindex="-1">(1) 功能实现 <a class="header-anchor" href="#_1-功能实现" aria-label="Permalink to &quot;(1) 功能实现&quot;">​</a></h4><ul><li><strong>部分读取/写入</strong>：旧版 EC 需读取完整条带，新版仅读取所需块，减少冗余 IO。</li><li><strong>优化写入</strong>：经典方法与 Parity Delta Writes 技术结合，减少数据读取和写入量。</li><li><strong>空间效率提升</strong>：小对象写入时避免零填充，实际存储空间占用显著降低。</li></ul><h4 id="_2-恢复与校验优化" tabindex="-1">(2) 恢复与校验优化 <a class="header-anchor" href="#_2-恢复与校验优化" aria-label="Permalink to &quot;(2) 恢复与校验优化&quot;">​</a></h4><ul><li><strong>Rebalance</strong>：仅迁移必要数据，减少迁移过程中的 IO 操作。</li><li><strong>Deep Scrub</strong>：新增对 EC 池的 CRC 校验支持，提升性能。</li></ul><h4 id="_3-兼容性与部署" tabindex="-1">(3) 兼容性与部署 <a class="header-anchor" href="#_3-兼容性与部署" aria-label="Permalink to &quot;(3) 兼容性与部署&quot;">​</a></h4><ul><li><strong>向后兼容</strong>：升级后默认禁用优化，需通过 <code>allow_ec_optimizations</code> 标志启用。</li><li><strong>客户端兼容性</strong>：仅需升级核心组件，无需更新客户端。</li></ul><h4 id="_3-性能数据" tabindex="-1">3. 性能数据 <a class="header-anchor" href="#_3-性能数据" aria-label="Permalink to &quot;3. 性能数据&quot;">​</a></h4><ul><li><strong>读性能</strong>：接近 replica 3 的延迟表现，未来通过 Direct Reads 进一步优化。</li><li><strong>写性能</strong>：所有测试场景均优于旧版，随机写入吞吐量提升显著。</li><li><strong>CPU 与网络</strong>：CPU 开销减少，网络流量下降。</li></ul><h4 id="_4-配置建议" tabindex="-1">4. 配置建议 <a class="header-anchor" href="#_4-配置建议" aria-label="Permalink to &quot;4. 配置建议&quot;">​</a></h4><ul><li><strong>条带大小</strong>：默认 4K，新池推荐 16K 条带。</li><li><strong>启用命令</strong>：<code>ceph osd pool set &lt;pool&gt; allow_ec_optimizations true</code></li></ul><h4 id="_5-后续计划" tabindex="-1">5. 后续计划 <a class="header-anchor" href="#_5-后续计划" aria-label="Permalink to &quot;5. 后续计划&quot;">​</a></h4><ul><li><strong>待实现功能</strong>：Direct Reads/Writes、分布式 Parity Delta Writes。</li><li><strong>性能持续优化</strong>：对齐 replica 3 的成熟度。</li></ul><h4 id="_6-q-a-摘要" tabindex="-1">6. Q&amp;A 摘要 <a class="header-anchor" href="#_6-q-a-摘要" aria-label="Permalink to &quot;6. Q&amp;A 摘要&quot;">​</a></h4><ul><li>新版 EC 性能优于旧版，16K 条带效果最佳。</li><li>CPU 利用率降低，性能提升。</li></ul><h4 id="行动项" tabindex="-1">行动项 <a class="header-anchor" href="#行动项" aria-label="Permalink to &quot;行动项&quot;">​</a></h4><ul><li>IBM 团队继续收集性能数据，发布优化细节博客。</li><li>社区用户测试 Tentacle RC 版本，反馈实际场景性能。</li><li>文档团队更新 EC 配置指南，明确 16K 条带建议。</li></ul>',21)])])}const g=e(o,[["render",i]]);export{_ as __pageData,g as default};
